xpath.script:
// MCP mega-menu guard — inject ghost mobile toggles so Odoo's
// updateActiveMenuLinks() doesn't crash on undefined .classList.
(function(){
    function shim(){
        var collapse = document.querySelector("#top_menu_collapse_mobile");
        if(!collapse) return;
        var topMenu = collapse.querySelector(".top_menu");
        if(!topMenu){
            topMenu = document.createElement("ul");
            topMenu.className = "top_menu d-none";
            collapse.appendChild(topMenu);
        }
        var desktop = document.querySelectorAll("header .o_mega_menu_toggle, #top_menu .o_mega_menu_toggle");
        var mobile = topMenu.querySelectorAll(".o_mega_menu_toggle");
        for(var i=mobile.length;i<desktop.length;i++){
            var g = document.createElement("a");
            g.className = "o_mega_menu_toggle d-none";
            g.setAttribute("data-mega-menu-ghost","1");
            topMenu.appendChild(g);
        }
    }
    if(document.readyState==="loading"){
        document.addEventListener("DOMContentLoaded", shim);
    } else { shim(); }
})();
